import{_ as e,a0 as i,w as p,s as a,ao as s,I as o,x as n,a1 as r,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Ubuntu中跟蹤多個時區的簡捷方法 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu中跟蹤多個時區的簡捷方法 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu中跟蹤多個時區的簡捷方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu中跟蹤多個時區的簡捷方法 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141204 The Easy Way to Keep Track of Multiple Time Zones in Ubuntu","title":"Ubuntu中跟蹤多個時區的簡捷方法","tag":"201502","desc":""},"relativePath":"201502/20141204 The Easy Way to Keep Track of Multiple Time Zones in Ubuntu.md","filePath":"[post].md"}'),g={name:"201502/20141204 The Easy Way to Keep Track of Multiple Time Zones in Ubuntu.md"};function m(d,t,T,b,f,C){const l=i("Link");return p(),a("div",null,[t[27]||(t[27]=s('<h1 id="ubuntu中跟蹤多個時區的簡捷方法" tabindex="-1">Ubuntu中跟蹤多個時區的簡捷方法 <a class="header-anchor" href="#ubuntu中跟蹤多個時區的簡捷方法" aria-label="Permalink to “Ubuntu中跟蹤多個時區的簡捷方法”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/date-time.jpg" alt="date-time"></p><p><strong>無論我是要在醒來時發個關於澳大利亞的 Chromebook 銷售已經售罄的推特，還是要記着和Ohso的半個開發商山姆陳進行Skype通話，我大腦都需要同時工作在多個時區下。</strong></p><p>那裏頭有個問題，如果你認識我，你會知道我的腦容量也就那麼丁點，跟金魚差不多，裏頭卻塞着像Windows Vista這樣一個臃腫貨（也就是，不是很好）。我幾乎記不得昨天之前的事情，更記不得我的門和金門大橋腳之間的時間差！</p><p>作為臂助，我使用一些小部件和菜單項來讓我保持同步。在我常規工作日的空間裏，我在多個操作系統間游弋，涵蓋移動系統和桌面系統，但只有一個可以讓我最快速便捷地設置“世界時鐘”。</p><p><strong>它的名字就是我們標題上提到的那個。</strong></p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/timezones-300x180.jpg" alt=""></p><h3 id="添加世界時鐘到ubuntu日期-時間小應用" tabindex="-1">添加世界時鐘到Ubuntu日期/時間小應用 <a class="header-anchor" href="#添加世界時鐘到ubuntu日期-時間小應用" aria-label="Permalink to “添加世界時鐘到Ubuntu日期/時間小應用”">​</a></h3><p>Unity中默認的日期-時間指示器提供了添加並查看多個時區的支持，不需要附加組件，不需要額外的包。</p><ol><li>點擊時鐘小應用，然後選擇‘<strong>時間和日期設置</strong>’條目</li><li>在‘<strong>時鐘</strong>’標籤中，選中‘<strong>其它位置的時間</strong>’選框</li><li>點擊‘<strong>選擇位置</strong>’按鈕</li><li>點擊‘<strong>+</strong>’，然後輸入位置名稱</li></ol><h4 id="其它桌面環境" tabindex="-1">其它桌面環境 <a class="header-anchor" href="#其它桌面環境" aria-label="Permalink to “其它桌面環境”">​</a></h4><p><strong>KDE Plasma</strong>中默認的時鐘小應用有類似的功能，其它功能如下：</p><ol><li>在數字時鐘小部件上右擊，然後選擇‘<strong>數字時鐘設置</strong>’</li><li>點擊‘<strong>時區</strong>’項</li><li>在搜索區輸入城市名</li><li>點擊‘<strong>確定</strong>’</li></ol>',13)),o("p",null,[t[1]||(t[1]=o("strong",null,"GNOME Shell",-1)),t[2]||(t[2]=n("的可擴展特性可以看到有許多世界時鐘選項可用，可以用它的默認時間表填補左邊的空白，我個人喜歡‘",-1)),r(l,{href:"https://extensions.gnome.org/extension/605/multiclock/"},{default:u(()=>[...t[0]||(t[0]=[n("多個時鐘",-1)])]),_:1}),t[3]||(t[3]=n("’。對於",-1)),t[4]||(t[4]=o("strong",null,"Cinnamon",-1)),t[5]||(t[5]=n("桌面而言也是一樣的，它的‘面板小部件’倉庫有豐富的可選部件，如超級順滑的“",-1)),t[6]||(t[6]=o("strong",null,"世界時鐘日曆",-1)),t[7]||(t[7]=n("”。",-1))]),t[28]||(t[28]=s('<p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/12/cinnamon-applet.jpg" alt="World Clock Calendar in Cinnamon 2.4"></p><p><em>Cinnamon 2.4中的世界時鐘日曆</em></p><p><strong>XFCE</strong>和<strong>LXDE</strong>就不那麼慷慨了，除了自帶的“工作區”作為<strong>多個時鐘</strong>添加到面板外，每個都需要手動配置以指定位置。兩個都支持‘指示器小部件’，所以，如果你不用Unity的話，你可以安裝/添加單獨的日期/時間指示器。</p><p><strong>Budgie</strong>還剛初出茅廬，不足以勝任這種角落裏的需求，因為Pantheon我還沒試過——希望你們通過評論來讓我知道得更多。</p><h4 id="桌面應用、部件和conky主題" tabindex="-1">桌面應用、部件和Conky主題 <a class="header-anchor" href="#桌面應用、部件和conky主題" aria-label="Permalink to “桌面應用、部件和Conky主題”">​</a></h4><p>當然，面板小部件只是收納其它國家多個時區的一種方式。如果你不滿意通過面板去訪問，那裏還有各種各樣的<strong>桌面應用</strong>可供使用，其中許多都可以跨版本，甚至跨平台使用。</p>',6)),o("p",null,[t[9]||(t[9]=o("strong",null,"GNOME時鐘",-1)),t[10]||(t[10]=n("就是這樣一個應用，在Ubuntu 14.04 LTS及其後續版本中，你可以通過Ubuntu軟件中心直接安裝。",-1)),t[11]||(t[11]=o("strong",null,"Conky",-1)),t[12]||(t[12]=n("是一個很有潛力的備選（儘管我還沒發現有哪個預製主題為此目的設計），而其它像",-1)),r(l,{href:"http://www.omgchrome.com/calendar-clock-chrome-app/"},{default:u(()=>[...t[8]||(t[8]=[n("日曆時鐘",-1)])]),_:1}),t[13]||(t[13]=n("這樣輕量級的Chrome應用可以在任何安裝有Chrome這個免費瀏覽器的地方工作。",-1))]),t[29]||(t[29]=o("p",null,[o("strong",null,"你也關注時區嗎？如果是，你使用什麼應用、採用什麼方法或者小部件讓它顯示在頂層呢？")],-1)),t[30]||(t[30]=o("hr",null,null,-1)),o("p",null,[t[15]||(t[15]=n("via: ",-1)),r(l,{href:"http://www.omgubuntu.co.uk/2014/12/add-time-zones-world-clock-ubuntu"},{default:u(()=>[...t[14]||(t[14]=[n("http://www.omgubuntu.co.uk/2014/12/add-time-zones-world-clock-ubuntu",-1)])]),_:1})]),o("p",null,[t[19]||(t[19]=n("作者：",-1)),r(l,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[16]||(t[16]=[n("Joey-Elijah Sneddon",-1)])]),_:1}),t[20]||(t[20]=n(" 譯者：",-1)),r(l,{href:"https://github.com/GOLinux"},{default:u(()=>[...t[17]||(t[17]=[n("GOLinux",-1)])]),_:1}),t[21]||(t[21]=n(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:u(()=>[...t[18]||(t[18]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=n("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[22]||(t[22]=[n("LCTT",-1)])]),_:1}),t[25]||(t[25]=n(" 原創翻譯，",-1)),r(l,{href:"http://linux.cn/"},{default:u(()=>[...t[23]||(t[23]=[n("Linux中國",-1)])]),_:1}),t[26]||(t[26]=n(" 榮譽推出",-1))])])}const y=e(g,[["render",m]]);export{x as __pageData,y as default};
